    public static final Endpoint<QueryStationStatsRequest, QueryStationStatsResponse> QUERY_STATION_STATS = new Endpoint<>("query_station_stats", QueryStationStatsRequest.class, QueryStationStatsResponse.class, true, "/evcs/v1/query_station_stats");
