    public static final Endpoint<QueryEquipChargeStatusRequest, QueryEquipChargeStatusResponse> QUERY_EQUIP_CHARGE_STATUS = new Endpoint<>("query_equip_charge_status", QueryEquipChargeStatusRequest.class, QueryEquipChargeStatusResponse.class, true, "/evcs/v1/query_equip_charge_status");
    public static final Endpoint<ChargingSnapshot, NotificationEquipChargeStatusResponse> NOTIFICATION_EQUIP_CHARGE_STATUS = new Endpoint<>("notification_equip_charge_status", ChargingSnapshot.class, NotificationEquipChargeStatusResponse.class, true, "/notification_equip_charge_status");
