    public static final Endpoint<NotificationStopChargeResultRequest, NotificationStopChargeResultResponse> NOTIFICATION_STOP_CHARGE_RESULT = new Endpoint<>("notification_stop_charge_result", NotificationStopChargeResultRequest.class, NotificationStopChargeResultResponse.class, true, "/notification_stop_charge_result");
    public static final Endpoint<ChargeOrderInfo, NotificationChargeOrderInfoResponse> NOTIFICATION_CHARGE_ORDER_INFO = new Endpoint<>("notification_charge_order_info", ChargeOrderInfo.class, NotificationChargeOrderInfoResponse.class, true, "/notification_charge_order_info");
    public static final Endpoint<CheckChargeOrdersRequest, CheckChargeOrdersResponse> CHECK_CHARGE_ORDERS = new Endpoint<>("check_charge_orders", CheckChargeOrdersRequest.class, CheckChargeOrdersResponse.class, true, "/check_charge_orders");
    public static final Endpoint<QueryOpenLinkRequest, QueryOpenLinkResponse> QUERY_OPEN_LINK = new Endpoint<>("query_open_link", QueryOpenLinkRequest.class, QueryOpenLinkResponse.class, true, "/evcs/v1/query_open_link");
